  'aprova-cot': (d) => { const c = db.cotacoes.find((x) => x.st === 'aberta'), fi = Number(d.f), total = soma(c.itens, (it) => it.qtd * it.precos[fi]); c.st = 'aprovada'; db.pedidos.push({ id: `pd${Date.now().toString(36)}`, forn: FORN[fi], itens: c.itens.map((it) => ({ cod: it.cod, qtd: it.qtd, custo: it.precos[fi] })), total, st: 'pedido', dia: 0 }); registra(`comprou a reposição com ${FORN[fi]} (${R$(total)})`); guarda(); desenha(); aviso(`Pedido de ${R$(total)} enviado para ${FORN[fi]}.`); },
  'chegou-ped': (d) => { const p = db.pedidos.find((x) => x.id === d.id); p.st = 'recebido'; p.itens.forEach((it) => { const pc1 = db.pecas.find((x) => x.cod === it.cod); if (pc1) { pc1.custo = Math.round((pc1.custo * pc1.estoque + it.custo * it.qtd) / (pc1.estoque + it.qtd) * 100) / 100; pc1.estoque += it.qtd; } }); registra(`recebeu o pedido da ${p.forn}`); guarda(); desenha(); aviso('Estoque atualizado com o custo novo.'); },
  'nova-garantia': () => form('Garantia de fabricante', '<label class="campo">Peça que voltou<input name="p" required placeholder="Ex.: Bomba de combustível (Onix)"></label><div class="par"><label class="campo">Fabricante<input name="f" required></label><label class="campo">Valor (R$)<input name="v" inputmode="decimal" required></label></div>', 'Registrar', (f) => { const v = Number(String(f.get('v')).replace(/\./g, '').replace(',', '.')); if (!(v > 0)) return 'Informe o valor.'; db.garantias.push({ id: `g${Date.now().toString(36)}`, peca: String(f.get('p')).trim(), fab: String(f.get('f')).trim(), valor: v, status: 'a enviar', dias: 0 }); registra(`registrou garantia de ${f.get('p')}`); }),
  'gar-res': (d) => { const g = db.garantias.find((x) => x.id === d.id); g.status = d.v; registra(`garantia de ${g.peca}: ${d.v}`); guarda(); desenha(); aviso(d.v === 'negada' ? 'Negada: a peça entra como perda.' : d.v === 'creditada' ? `${R$(g.valor)} recuperados.` : 'Aprovada: aguarde o crédito.'); },
  'nps-resp': () => form('Resposta da pesquisa', `<div class="par"><label class="campo">Unidade<select name="u">${opUn(db.un !== 'todas' ? db.un : Object.keys(UNIDADES)[0])}</select></label><label class="campo">Nota (0 a 10)<input name="n" type="number" min="0" max="10" required></label></div><label class="campo">Cliente<input name="c" required></label><label class="campo">Comentário<input name="m"></label>`, 'Lançar', (f) => { const n = Math.round(Number(f.get('n'))), u = f.get('u'); if (!(n >= 0 && n <= 10)) return 'Nota de 0 a 10.'; db.nps[u][n >= 9 ? 0 : n >= 7 ? 1 : 2]++; if (n <= 6) db.detratores.push({ id: `d${Date.now().toString(36)}`, nome: String(f.get('c')).trim(), un: u, nota: n, motivo: String(f.get('m') || 'sem comentário').trim(), ligou: false }); registra(`lançou nota ${n} de ${f.get('c')} (${UNIDADES[u]})`); if (n <= 6) aviso('Cliente crítico: ele entrou na lista para ligar.'); }),
  'orc-ok': (d) => { const o = db.orcamentos.find((x) => x.id === d.id); o.st = 'aprovado'; registra(`orçamento de ${o.cliente} aprovado (${R$(o.valor)})`); guarda(); desenha(); aviso('Aprovado: abra a OS e reserve o box.'); },
  'orc-perdido': (d) => { const o = db.orcamentos.find((x) => x.id === d.id); form(`Perdido · ${e(o.cliente)}`, '<label class="campo">Motivo<select name="m"><option>Achou mais barato</option><option>Vai fazer depois</option><option>Fez na concessionária</option><option>Não respondeu</option></select></label>', 'Registrar', (f) => { o.st = 'perdido'; o.motivo = f.get('m'); registra(`orçamento de ${o.cliente} perdido: ${o.motivo}`); }); },
  'rev-agendou': (d) => { const r = db.revisoes.find((x) => x.id === d.id); r.st = 'agendado'; registra(`agendou revisão de ${r.nome}`); guarda(); desenha(); },
  'veic-frota': (d) => { const f = db.frotas.find((x) => x.id === d.f); form(`Veículo · ${e(f.empresa)}`, '<div class="par"><label class="campo">Placa<input name="p" required style="text-transform:uppercase"></label><label class="campo">Modelo<input name="m" required></label></div><label class="campo">Próxima preventiva em (dias)<input name="d" type="number" min="0" value="30"></label>', 'Incluir', (fm) => { const placa = String(fm.get('p')).toUpperCase().replace(/[^A-Z0-9]/g, ''); if (placa.length < 7) return 'Placa inválida.'; if (f.proximas.some((p) => p[0] === placa)) return 'Esse veículo já está no contrato.'; const dd = Math.max(0, Math.round(Number(fm.get('d')) || 0)); f.proximas.push([placa, String(fm.get('m')).trim(), dd === 0 ? 'vence hoje' : `em ${dd} dias`]); f.veiculos++; registra(`incluiu ${placa} no contrato da ${f.empresa}`); }); },
  cotar: () => { if (db.cotacoes.some((x) => x.st === 'aberta')) return aviso('Já há uma cotação aberta: escolha o fornecedor.'); const l = db.pecas.filter((p) => p.estoque / (p.vendas / 365) < 30); if (!l.length) return aviso('Nenhum item com menos de 30 dias de estoque.'); const k = [1, 0.94, 0.89]; db.cotacoes.push({ id: `c${Date.now().toString(36)}`, st: 'aberta', prazos: [1, 2, 4], itens: l.map((p, i) => ({ cod: p.cod, qtd: Math.max(1, Math.round(p.vendas / 12 * 1.5 - p.estoque)), precos: k.map((x, fi) => Math.round(p.custo * x * (1 + ((i + fi) % 3) * 0.02) * 100) / 100) })) }); registra(`abriu cotação de reposição com ${l.length} itens`); guarda(); desenha(); aviso(`Cotação de ${l.length} itens enviada para 3 fornecedores: as respostas estão em Peças.`); },
